    pOwnedObject = 0;
    m_kPrimaryTopicList.RemoveAll();
    m_kSecondaryTopicList.RemoveAll();
    m_pAuxiliaryList->RemoveAll();
    ClearMuzzleFlash();
    m_pCurrentDialogueItem = 0;
    ClearAndDeleteList();
    for (i = 0; i < 6; ++i)
    {
        m_pRecentReferences[i] = 0;
        m_bReferenceFlags[i] = false;
    }
    coordinate = 0;
