// @fnv 0x008fec10
bool HighProcess::ClearProcessState(Actor* actor)
{
    float delta;
    if (m_iSecondSerializedValue == BaseProcess::FadeNone)
    {
        if (fFadeAlpha >= 1.0)
            return false;
        else
        {
            fFadeAlpha = 1.0f;
            actor->UpdateActorPresentation();
            return false;
        }
    }
    if (actor == (Actor*)g_thePlayer)
        delta = (float)(((const NiBound*)&g_timeGlobal)->FUN_0084d030() / originalRuntimeFloatSetting109.Float()->f);
    else
        delta = (float)(((const NiBound*)&g_timeGlobal)->FUN_0084d030() / originalRuntimeFloatSetting108.Float()->f);
    if (m_iSecondSerializedValue == BaseProcess::FadeInState || m_iSecondSerializedValue == BaseProcess::FadeTeleportIn)
    {
        fFadeAlpha += delta;
        if (fFadeAlpha > 1.0)
        {
            fFadeAlpha = 1.0f;
            m_iSecondSerializedValue = BaseProcess::FadeNone;
        }
    }
    else if (m_iSecondSerializedValue == BaseProcess::FadeOutState)
    {
        if (fFadeAlpha > 0.0)
        {
            fFadeAlpha -= delta;
            if (fFadeAlpha < 0.0)
            {
                fFadeAlpha = 0.0f;
                m_pFadeReference = 0;
            }
        }
    }
    else if (m_iSecondSerializedValue == BaseProcess::FadeMove)
    {
        if (fFadeAlpha > 0.0)
        {
            fFadeAlpha -= delta;
            if (fFadeAlpha <= 0.0)
            {
                fFadeAlpha = 0.0f;
                if (pDetectionEventData)
                {
                    Script::MoveReferenceToPosition(actor, pDetectionEventData->target, pDetectionEventData->position.x,
                                                    pDetectionEventData->position.y, pDetectionEventData->position.z);
                    delete pDetectionEventData;
                }
                pDetectionEventData = 0;
                m_pFadeReference = 0;
            }
        }
    }
    else if (m_iSecondSerializedValue == BaseProcess::FadeTeleportOut)
    {
        if (actor == (Actor*)g_thePlayer)
        {
            fFadeAlpha = 1.0f;
            TESObjectREFR* teleport = m_pFadeReference;
            m_pFadeReference = 0;
            if (teleport)
                teleport->Activate(actor, false, 0, 1);
            m_iSecondSerializedValue = BaseProcess::FadeNone;
            return true;
        }
        else
        {
            fFadeAlpha -= delta;
            if (fFadeAlpha < 0.0)
            {
                fFadeAlpha = 0.0f;
                TESObjectREFR* teleportOther = m_pFadeReference;
                m_pFadeReference = 0;
                if (teleportOther)
                    teleportOther->Activate(actor, false, 0, 1);
                if (actor == (Actor*)g_thePlayer || !actor->GetProcessTier())
                    ProcessActorWithFlag(actor, true);
                else
                {
                    m_iSecondSerializedValue = BaseProcess::FadeNone;
                    return true;
                }
            }
        }
    }
    else if (m_iSecondSerializedValue == BaseProcess::FadeDelete)
    {
        fFadeAlpha -= delta;
        if (fFadeAlpha < 0.0)
        {
            fFadeAlpha = 0.0f;
            actor->SetDeleted(true);
        }
    }
    else if (m_iSecondSerializedValue == BaseProcess::FadeDisable)
    {
        fFadeAlpha -= delta;
        if (fFadeAlpha < 0.0)
        {
            fFadeAlpha = 0.0f;
            actor->Disable();
        }
    }
    actor->UpdateActorPresentation();
    return FUN_008ff080();
}

