// Runs the package decision for subject: acquires/updates the actor, picks a target, applies or releases based on distance checks and package flags.
// @fnv 0x008ddac0
void ProcessDDA::ProcessActorPackage(ActorDDA* subject)
{
    PackageDDA* e = currentPackage();
    if (subject->special())
    {
        fallback(subject, 1);
        return;
    }
    if (!actor)
        acquire(subject);
    update(subject, 0);
    RefDDA* s = e->FUN_00671d10();
    if (!actor && s)
        setTarget(s->FUN_00680020());
    RefDDA* f = target();
    RefDDA* a = alternateTarget();
    if (!f && !a)
    {
        fallback(subject, 1);
        return;
    }
    float h = (float)e->FUN_00676280(subject);
    float i = s ? (float)s->FUN_0044ddc0() : -1.0f;
    bool p = a ? h < subject->FUN_005723b0(a, 0, 0) : i > subject->FUN_005723b0(f, 0, 0);
    if (p)
    {
        RefDDA* p = f;
        subject->apply(p, 1, 1, 0, 0, a, i, h);
        PackageDDA* a = currentPackage();
        PackageDDA* h = 0;
        if (a && a->FUN_0041ca90() == 22)
            h = a;
        if (h && p)
            h->FUN_009f1310(p);
        return;
    }
    else if (!subject->FUN_008b3bb0())
    {
        release(subject);
        AnimDDA* p = subject->animation();
        if (p && p->SpecialIdleDonePlaying())
            action(subject, 0, 2, 1, 0, 1);
    }
    else if (e->FUN_0067efd0() || e->FUN_008b1ff0())
    {
        release(subject);
        flag(1);
        fallback(subject, 1);
        finish(subject, 0);
    }
}

