// @fnv 0x008f7730
bool UWProcess::FUN_008f7730(UWActor* actor)
{
    UWPackage* package = GetCurrentPackage();
    if (actor->GetDistanceToReference(g_pPlayerRef, false, false) > *gs_fUseWeaponMaxDistance.Float())
        return true;

    int roll2 = DialogueRandom() % 100;
    UWWeapon* weapon = 0;
    UWForm* useObject = 0;
    UWRef* locRef = 0;
    UWPackageLocation* location3 = package->GetPackageLocation();
    UWInventoryChanges* pInventoryB = CreateForReference(actor);
    UWPackageTarget* target = package->GetPackageTarget();
    UWUseWeaponData* kData = package->GetWeaponUseData();
    SetupUseWeapon(actor);

    if (location3 && location3->GetLocationReference())
        locRef = location3->GetLocationReference();
    if (!locRef)
        locRef = m_pReference40;

    if (!package->IsValidForReferences(actor, 0, -1.0f, 0))
    {
        UpdateActorBehavior(actor);
        EndPackage(actor, -1);
        return false;
    }
    else if (locRef && locRef->GetBaseObject() == g_pCombatMarker && !m_bPackageStateFlag)
    {
        float headingCur = 0.0f;
        headingCur = locRef->GetAngleOnReference().z;
        float headingDelta2 = 0.0f;
        float angleDelta = GetInterpolatedFloat(actor->GetCurrentTargetDistance(0), headingCur, &headingDelta2);
        float maxAngle = *gs_iUseWeaponMaxAngle.Int() * 0.01745329238474369;
        if (FloatAbs(angleDelta) > maxAngle)
        {
            actor->SetReferenceHeading(headingCur, false);
            SetTurning(false);
            return false;
        }
        else
        {
            actor->StopMoving();
            SetStopped(true);
            actor->SetFurnitureHeading(locRef->GetAngleOnReference().z);
            ResetMovement(actor);
        }
    }
    else if (actor->IsMoving())
    {
        actor->StopMoving();
        ResetMovement(actor);
    }

    UWRef* combatTarget2 = 0;
    UWCombatProcedure* procedureTmp = GetCombatProcedure();
    if (procedureTmp)
        combatTarget2 = procedureTmp->GetTarget();
    if (!combatTarget2)
    {
        combatTarget2 = locRef;
        UWPackageTarget* attackTarget = kData->GetTarget();
        if (attackTarget)
        {
            switch (attackTarget->GetTargetKind())
            {
            case 0:
                combatTarget2 = attackTarget->GetReferenceTarget();
                break;
            case 3:
                combatTarget2 = actor->GetLinkedRef();
                break;
            case 1:
            case 2:
                char message[256];
                FormatTextBuffer(
                    message, 256,
                    "UseWeapon package %s should have a referenceas its attack target; object/type targets are not supported (yet).",
                    package->GetEditorName());
                Warning(message);
                break;
            }
        }
        if (procedureTmp)
            procedureTmp->Initialize(combatTarget2);
    }

    if (!target)
    {
        m_ePackageObjectType = 0;
    }
    else
    {
        if (pTarget && (!target->GetTargetKind() || target->GetTargetKind() == 3))
        {
            useObject = pTarget->GetBaseObject();
            m_ePackageObjectType = GetFormTypeCode(pTarget->GetBaseObject());
        }
        else if (target->GetTargetKind() == 1)
        {
            useObject = target->GetTargetForm();
            m_ePackageObjectType = GetFormTypeCode(useObject);
        }
        else if (target->GetTargetKind() == 2)
        {
            m_ePackageObjectType = target->GetTargetObjectType();
        }
        if (pTarget && !m_ePackageObjectType)
        {
            useObject = pTarget->GetBaseObject();
            m_ePackageObjectType = GetFormTypeCode(pTarget->GetBaseObject());
            if (m_pReference40)
            {
                SetUseTarget(m_pReference40);
                useObject = m_pReference40->GetBaseObject();
                m_ePackageObjectType = GetFormTypeCode(m_pReference40->GetBaseObject());
            }
            else
            {
                m_ePackageObjectType = 0;
            }
        }
    }

    if (GetWeaponEntry() && GetWeaponEntry()->GetObject() && GetWeaponEntry()->GetObject()->GetFormType() == 0x28)
        weapon = (UWWeapon*)GetWeaponEntry()->GetObject();

    switch (m_ePackageObjectType)
    {
    case 0xc:
    case 0xd:
    case 0x15:
    case 0x16:
    case 0x17:
        break;
    default:
        char message2[256];
        FormatTextBuffer(message2, 256, "UseWeapon package %s has a non-weapon target; should be UseItem.",
                         package->GetEditorName());
        Warning(message2);
        return false;
    }

    target = package->GetPackageTarget();
    if (!CanUseWeapon(actor, true) && m_ePackageObjectType != 0x15)
    {
        UpdateActorBehavior(actor);
        EndPackage(actor, 2);
        return false;
    }

    if (weapon)
    {
        switch (target->GetTargetKind())
        {
        case 1:
            if (weapon != target->GetTargetForm())
            {
                actor->EquipInventoryItem(target->GetTargetForm(), 1, 0, true, false, true);
                return true;
            }
            break;
        case 0:
        case 3: {
            UWRef* useRef = GetUseTargetEntry()->GetRef();
            if (useRef && weapon != useRef->GetBaseObject())
            {
                actor->EquipInventoryItem(useRef->GetBaseObject(), 1, 0, true, false, true);
                return true;
            }
        }
        break;
        case 2:
            if (!MatchesFormType(weapon, target->GetTargetObjectType()))
            {
                int count = 0;
                UWForm* item = pInventoryB->GetBoundObjectByIndex(m_ePackageObjectType, &count);
                if (item)
                {
                    actor->EquipInventoryItem(item, 1, 0, true, false, true);
                    return true;
                }
            }
            break;
        }
    }

    if (m_sSecondIndex <= 0 && weapon)
    {
        m_sSecondIndex = BSMax(1, weapon->GetClipRounds(false));
        if (kData && kData->IsVolleyFire())
        {
            int volley = GetRandomNumberInRange(kData->GetVolleyShotsMin(), kData->GetVolleyShotsMax());
            m_sSecondIndex = volley > 0 ? volley : m_sSecondIndex;
        }
    }

    if (m_sSecondIndex > 0 && m_sFirstIndex >= m_sSecondIndex)
    {
        m_sThirdIndex++;
        m_sSecondIndex = -1;
        m_sFirstIndex = 0;
        bool thrownDone =
            weapon && weapon->IsMeleeWeapon() && !kData->GetRepeatFire() && m_sThirdIndex >= kData->GetBurstCount();
        if (thrownDone)
        {
            actor->SetIsSwimming(false);
            actor->UnequipObject(weapon, 1, 0, false, false, true);
            m_fSecondAnimationValue = 0.0f;
        }
        else if (kData->IsVolleyFire())
        {
            m_fSecondAnimationValue = RandomFloat(kData->GetVolleyWaitMin(), kData->GetVolleyWaitMax());
        }
    }

    if (kData && kData->IsCrouch() && !package->GetAlwaysSneak())
    {
        UWAnimation* animation = actor->GetAnimation();
        UWItemEntry* ammo2 = GetAmmoEntry();
        bool needReloadA = ammo2 && ammo2->GetCount() <= 1 && weapon && weapon->GetAmmoPerShot() > 0;
        bool reloading = actor->HasWeaponDrawn() || (animation && animation->ReloadAnimQueued());
        int groupType2 = GetAnimGroupType(animation->GetGroup(4));
        bool attacking = groupType2 >= 0x18 && groupType2 <= 0xa8;
        bool crouchTmp = !attacking && (needReloadA || reloading);
        bool idle = GetAnimGroupMove(animation->GetGroup(0)) == 1;
        actor->SetForceSneak(crouchTmp);
        if (needReloadA)
        {
            if (attacking)
            {
                animation->BlendOut(4, false);
            }
            else if (idle && !reloading)
            {
                UWSequence* sequence = animation->GetCurrentSequence(0);
                bool sequenceDone = sequence && sequence->GetState() == 1;
                if (sequenceDone)
                    actor->DrawWeapon();
            }
        }
        if (crouchTmp || idle || (needReloadA && attacking))
        {
            if (combatTarget2)
                UpdateCombatTarget(actor, combatTarget2, false);
            if (combatTarget2)
                SetMovementTarget(combatTarget2);
            return false;
        }
    }
    else if (weapon && !weapon->IsMeleeWeapon())
    {
        UWAnimation* anim = actor->GetAnimation();
        UWItemEntry* ammoEntryA = GetAmmoEntry();
        bool outOfAmmo_ = ammoEntryA && ammoEntryA->GetCount() <= 1 && weapon && weapon->GetAmmoPerShot() > 0;
        unsigned int animFlags = GetAnimFlags();
        bool busy = actor->HasWeaponDrawn() || (anim && anim->ReloadAnimQueued()) || (animFlags & 2);
        if (outOfAmmo_ && !busy)
        {
            actor->DrawWeapon();
            return false;
        }
    }

    if (!package->IsValidForReferences(actor, 0, -1.0f, 0))
    {
        RefreshActorPackage(actor);
        EndPackage(actor, -1);
        return false;
    }

    if (GetWeaponEntry())
    {
        weapon = 0;
        if (GetWeaponEntry()->GetObject() && GetWeaponEntry()->GetObject()->GetFormType() == 0x28)
            weapon = (UWWeapon*)GetWeaponEntry()->GetObject();
    }

    if (m_ePackageObjectType == 0x15)
    {
        if (weapon)
        {
            actor->UnequipObject(weapon, 1, 0, false, false, true);
            return true;
        }
    }
    else if (!weapon)
    {
        UWForm* newWeaponA = 0;
        int itemCount = 0;
        UWItemEntry* entry3 = 0;
        if (pTarget)
            entry3 = pInventoryB->FindEntryForObject(pTarget->GetBaseObject(), 0);
        else if (useObject)
            entry3 = pInventoryB->FindEntryForObject(useObject, 0);
        else
            newWeaponA = pInventoryB->GetBoundObjectByIndex(m_ePackageObjectType, &itemCount);
        if (!newWeaponA && entry3)
            newWeaponA = entry3->GetObject();
        if (newWeaponA)
        {
            actor->EquipInventoryItem(newWeaponA, 1, 0, true, false, true);
        }
        else
        {
            UpdateActorBehavior(actor);
            EndPackage(actor, 2);
        }
        if (entry3)
            actor->EquipInventoryItem(entry3->GetObject(), 1, 0, true, false, true);
        delete entry3;
        return true;
    }

    bool canFire3 = m_fSecondAnimationValue <= 0.0;
    if (canFire3 && !kData->GetRepeatFire() && m_sThirdIndex >= kData->GetBurstCount())
    {
        UpdateActorBehavior(actor);
        EndPackage(actor, 2);
        return true;
    }
    if (canFire3 && combatTarget2 && locRef != combatTarget2)
        canFire3 = UpdateCombatTarget(actor, combatTarget2, false);
    if (canFire3 && package->GetPackageSecondLocation() && combatTarget2)
    {
        if (combatTarget2->IsActorRef())
        {
            UWActor* targetActor = (UWActor*)combatTarget2;
            canFire3 = package->CheckTargetConditions(targetActor, actor, 0, -1.0f, 0);
        }
        else
        {
            canFire3 = false;
        }
    }

    if (canFire3 && kData && kData->IsHoldFireWhenBlocked())
    {
        float targetDistSqr = actor->GetDistanceToReference(combatTarget2, false, false);
        targetDistSqr = targetDistSqr * targetDistSqr;
        UWDetectionNode* node2 = pDetectionEventList;
        while (node2 && !node2->IsEmpty())
        {
            UWDetectionData* detected = node2->Item();
            node2 = node2->GetNext();
            if (detected->actor == combatTarget2)
                continue;
            if (detected->actor->IsDead(false))
                continue;
            if (!detected->bInLOS)
                continue;
            if (detected->m_iDetectionState <= 0)
                continue;
            UWPoint3 iOffset = detected->lastSeenPos;
            iOffset -= *actor->GetPos();
            if (iOffset.SqrLength() >= targetDistSqr)
                continue;
            float angle_ = IsDoor(iOffset);
            float delta;
            float aDiff = GetInterpolatedFloat(actor->GetCurrentTargetDistance(0), angle_, &delta);
            if (FloatAbs(aDiff) < 0.5235987901687622)
            {
                canFire3 = false;
                break;
            }
        }
    }

    if (!IsInIdleState() && !IsWeaponOut())
    {
        actor->SetIsSwimming(true);
        bWeaponAlertDrawn = true;
    }
    else if (canFire3)
    {
        int attackRoll = DialogueRandom() % 100;
        int attackGroupA = 0xff;
        UWWeapon* firingWeapon3 = 0;
        if (GetWeaponEntry())
        {
            firingWeapon3 = 0;
            if (GetWeaponEntry()->GetObject() && GetWeaponEntry()->GetObject()->GetFormType() == 0x28)
                firingWeapon3 = (UWWeapon*)GetWeaponEntry()->GetObject();
        }
        if (firingWeapon3 && firingWeapon3->GetWeaponType() >= 3)
        {
            ChangeWeapon(actor, firingWeapon3);
        }
        else if (actor->HasEssentialStatus())
        {
            if (GetCurrentAttackGroup() == -1)
            {
                if (combatTarget2 && combatTarget2->IsActorForm())
                {
                    UWActor* opponent = (UWActor*)combatTarget2;
                    if (attackRoll >= 40 && (opponent->GetAnimAction() == 2 || opponent->GetAnimAction() == 4))
                    {
                        actor->CanStartCombat(true);
                        m_fSecondAnimationValue = 1.2f;
                        return false;
                    }
                }
                UWAttackChoice attacks3[6] = {{0x5e, 10}, {0x60, 10}, {0x5c, 10}, {0x5f, 10}, {0x1a, 30}, {0x20, 30}};
                bool available[6];
                int totalWeight = 0;
                int i;
                for (i = 0; i < 6; i++)
                {
                    bool isAttack = IsActionTypeValid(actor->GetAnimGroup(attacks3[i].group, 0, 0, 0));
                    available[i] = isAttack;
                    totalWeight += isAttack ? attacks3[i].weight : 0;
                }
                i = 0;
                if (totalWeight > 0)
                {
                    int pick = DialogueRandom() % totalWeight;
                    for (; pick >= 0; i++)
                    {
                        if (!available[i])
                            continue;
                        pick -= attacks3[i].weight;
                        if (pick <= 0)
                            attackGroupA = attacks3[i].group;
                    }
                }
                UWPoint3 powerDelta;
                if (attackGroupA != -1 && GetPowerAttackDelta(actor, attackGroupA, &powerDelta) && powerDelta.y != 0.0)
                    attackGroupA = attackRoll <= 20 ? 0x1a : 0x20;
                if (actor->IsSneaking() && !IsSneakAttackBlocked() && !actor->IsSwimming())
                    attackGroupA = 0x5c;
                if (!actor->IsBlockActive())
                {
                    if (attackGroupA != -1 && actor->PlayAttackGroup(attackGroupA))
                        m_fSecondAnimationValue = 0.8f;
                }
                else
                {
                    m_fSecondAnimationValue = 0.8f;
                }
            }
            else if (actor->IsBlockActive())
            {
                actor->CanStartCombat(false);
            }
        }
    }
    else
    {
        RefreshActor(actor);
        SetAttacking(false);
        if (combatTarget2)
            UpdateCombatTarget(actor, combatTarget2, false);
        if (!package->IsValidForReferences(actor, 0, -1.0f, 0) && actor->GetAnimAction() == -1 &&
            actor->GetAnimation()->IsSequenceActive())
            EndPackage(actor, -1);
        if (m_fFirstAnimationValue <= 0.0)
            m_fSecondAnimationValue -= g_timer.GetSeconds();
    }

    if (combatTarget2)
        SetMovementTarget(combatTarget2);
    return false;
}

