// @fnv 0x008fe8f0
void C::SetContentCount(int unused, unsigned char flag)
{
    if (m_uiContentCount == 6 || m_uiContentCount == 5)
        return;
    m_uiContentCount = flag ? 3 : 1;
    m_zero = 0;
    if (m_uiFilterValue >= 1.0)
        m_uiFilterValue = 0.0f;
}

